const raw = $input.first()?.json ?? {};
const input = raw.body && typeof raw.body === 'object' ? raw.body : raw;

return [{
  json: {
    ...input,
  workflow_code: input.workflow_code ?? 'WF-017',
  source_code: input.source_code ?? 'SECOP_OPPORTUNITY_COMPLIANCE_EVALUATION',
  processing_mode: input.processing_mode ?? 'all',
  max_matrices: input.max_matrices ?? 10,
  evaluation_version: input.evaluation_version ?? 3,
  evaluation_method: input.evaluation_method ?? 'deterministic_v3',
  lock_minutes: input.lock_minutes ?? 30,
  stale_lock_minutes: input.stale_lock_minutes ?? 45,
    n8n_execution_id: String($execution.id ?? ''),
    trigger_type: String($execution.mode ?? 'manual'),
    configured_at: new Date().toISOString(),
  },
}];

