parameters.jsCode:
const input =
  $input.first()?.json ?? {};

const rawLockValue =
  input.lock_acquired;

const lockAcquired =
  rawLockValue === true
  || rawLockValue === 1
  || String(
    rawLockValue ?? ''
  )
    .trim()
    .toLowerCase() === 'true'
  || String(
    rawLockValue ?? ''
  )
    .trim() === '1';

return [
  {
    json: {
      ...input,

      lock_acquired_raw:
        rawLockValue ?? null,

      lock_acquired_boolean:
        lockAcquired,

      lock_acquired_flag:
        lockAcquired
          ? 1
          : 0,

      lock_route:
        lockAcquired
          ? 'LOCK_ACQUIRED'
          : 'LOCK_NOT_ACQUIRED',

      workflow_code:
        'WF-017',

      normalized_at:
        new Date().toISOString(),
    },
  },
];

const items = $input.all();

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

return items.map((item) => {
  const input =
    item.json ?? {};

  const rawHasMatrix =
    input.has_matrix;

  const rawBoolean =
    rawHasMatrix === true
    || rawHasMatrix === 1
    || String(rawHasMatrix ?? '')
      .trim()
      .toLowerCase() === 'true'
    || String(rawHasMatrix ?? '')
      .trim() === '1';

  const matrixId =
    String(
      input.matrix_id ?? ''
    ).trim();

  const hasValidMatrixId =
    uuidPattern.test(matrixId);

  const hasMatrix =
    rawBoolean
    && hasValidMatrixId;

  return {
    json: {
      ...input,

      has_matrix_raw:
        rawHasMatrix ?? null,

      has_matrix_boolean:
        hasMatrix,

      has_matrix_flag:
        hasMatrix
          ? 1
          : 0,

      has_valid_matrix_id:
        hasValidMatrixId,

      normalized_matrix_id:
        hasValidMatrixId
          ? matrixId
          : null,

      matrix_route:
        hasMatrix
          ? 'MATRIX_AVAILABLE'
          : 'NO_MATRICES',

      workflow_code:
        'WF-017',

      normalized_at:
        new Date().toISOString(),
    },
  };
});
